function routeIntoQuietRoom(){const step=.4,w=110,h=145,ox=-21.8,oz=-26.4,encode=(x,z)=>z*w+x,point=k=>new THREE.Vector3(ox+(k%w)*step,1.65,oz+Math.floor(k/w)*step);const cellOf=p=>[Math.round((p.x-ox)/step),Math.round((p.z-oz)/step)];const state=new Uint8Array(w*h),previous=new Int32Array(w*h).fill(-1);function free(x,z){if(x<0||z<0||x>=w||z>=h)return false;const k=encode(x,z);if(!state[k])state[k]=blocked(ox+x*step,oz+z*step)?2:1;return state[k]===1;}let [sx,sz]=cellOf(player);if(!free(sx,sz)){let found=false;for(let radius=1;radius<=4&&!found;radius++)for(let dx=-radius;dx<=radius&&!found;dx++)for(let dz=-radius;dz<=radius;dz++)if(free(sx+dx,sz+dz)){sx+=dx;sz+=dz;found=true;break;}if(!found)return[];}const [tx,tz]=cellOf(new THREE.Vector3(3,1.65,-7.55)),start=encode(sx,sz),goal=encode(tx,tz),queue=[start];previous[start]=start;for(let index=0;index<queue.length;index++){const k=queue[index];if(k===goal)break;const x=k%w,z=Math.floor(k/w);for(const [dx,dz]of [[0,-1],[1,0],[-1,0],[0,1]]){const nx=x+dx,nz=z+dz,n=encode(nx,nz);if(free(nx,nz)&&previous[n]===-1){previous[n]=k;queue.push(n);}}}if(previous[goal]===-1)return[];const path=[];for(let k=goal;k!==start;k=previous[k])path.push(point(k));path.reverse();path.push(new THREE.Vector3(3,1.65,-7.55));return path;}
