function forceEntry(){phase='forced_entry';phaseTime=0;keys.clear();verityMotion.hop=null;forcedPath=routeIntoQuietRoom();forcedIndex=0;say('Get in the rOoM, ▓̷̛͝R̸̢̍█̵̱̑Ő̷̹▒̸͎̿M̴̗̅▓, sWeEEtIe!',8);$('subtitle').classList.add('corrupt');objective('GET IN THE ROOM');sound(73,.35,.1,'sawtooth');if(!forcedPath.length){$('wake').hidden=false;$('wake').style.setProperty('--opening',0);}}
function updateForcedEntry(dt){if(!forcedPath.length){if(phaseTime<.65)return;player.set(3,1.65,-5.5);forcedPath=[new THREE.Vector3(3,1.65,-7.55)];forcedIndex=0;$('wake').hidden=true;}let remaining=dt*6.4;while(remaining>0&&forcedIndex<forcedPath.length){const target=forcedPath[forcedIndex],d=target.clone().sub(player);d.y=0;const length=d.length();if(length<.025){forcedIndex++;continue;}const amount=Math.min(length,remaining);d.normalize();player.addScaledVector(d,amount);remaining-=amount;const desired=Math.atan2(-d.x,-d.z),delta=Math.atan2(Math.sin(desired-yaw),Math.cos(desired-yaw));yaw+=delta*(1-Math.exp(-dt*12));}pitch*=Math.exp(-dt*7);if(forcedIndex>=forcedPath.length&&phaseTime>3.2){if(!inQuietRoom()){player.set(3,1.65,-7.55);}verity.position.set(4.7,.55,-7.7);verityMotion.hop=null;startDeparture();}}
function updateWake(){const t=phaseTime,smooth=x=>{x=Math.max(0,Math.min(1,x));return x*x*(3-2*x);};const open=t<.6?0:t<1.2?.3*smooth((t-.6)/.6):t<1.45?.3*(1-smooth((t-1.2)/.25)):t<2.5?.72*smooth((t-1.45)/1.05):t<2.75?.72-.5*smooth((t-2.5)/.25):.22+.78*smooth((t-2.75)/.9);$('wake').style.setProperty('--opening',open);const rise=smooth((t-2.8)/2.8);player.y=.3+1.35*rise;pitch=-.2*(1-rise);wakeRoll=-.32*(1-rise);$('scene').style.filter='blur('+Math.max(0,7*(1-smooth((t-1)/3.6)))+'px)';if(t>=5.8){phase='approach';phaseTime=0;player.y=1.65;pitch=0;wakeRoll=0;$('wake').hidden=true;$('scene').style.filter='none';$('controls').hidden=false;$('crosshair').hidden=false;}}
function updateStory(dt){phaseTime+=dt;verityMotion.wasMoving=false;const distance=player.distanceTo(verity.position);if(phase==='wake'){updateWake();return;}if(phase==='forced_entry'){updateForcedEntry(dt);verityMotion.idle(dt,player);return;}if(phase==='approach'){const approach=encounterStep===0?new THREE.Vector3(4.6,1.23,18):new THREE.Vector3(3,.55,15.6);if(walkNPC(approach,dt,3.8)){if(encounterStep===0){encounterStep++;}else{phase='greeting';phaseTime=0;if(!returningFromCatch)encounterMusic.start(audio);say(returningFromCatch?'I knew you would come back.':'hey! you look quite a bit lost. how about you come with me!',6);objective('LISTEN TO VERITY');}}}
 else if(phase==='greeting'&&phaseTime>6){phase='follow';phaseTime=0;objective('FOLLOW VERITY');}
 else if(phase==='follow'){if(!inQuietRoom())refusalTime+=dt;if((distance<6||verityMotion.hop)&&routeIndex<route.length){if(walkNPC(route[routeIndex],dt,3.1))routeIndex++;}if(routeIndex>=route.length){if(!startDeparture()){phase='await_entry';phaseTime=0;refusalTime=0;objective('ENTER THE QUIET ROOM');}}else if(refusalTime>45)forceEntry();}
 else if(phase==='await_entry'){if(!startDeparture()){refusalTime+=dt;if(refusalTime>18)forceEntry();}}
 else if(phase==='departure'){if(!inQuietRoom()){phase='await_entry';phaseTime=0;refusalTime=0;verityMotion.hop=null;objective('ENTER THE QUIET ROOM');}else if(phaseTime>5.5){const align=verity.position.z<-6.7&&Math.abs(verity.position.x-3)>.07;if(walkNPC(align?new THREE.Vector3(3,.55,-7.55):new THREE.Vector3(3,.55,-4.5),dt,3.6)&&!align){phase='closing';phaseTime=0;}}}
 else if(phase==='closing'){if(!inQuietRoom()){hinge.rotation.y=-Math.PI/2;doorProgress=0;phase='await_entry';phaseTime=0;refusalTime=0;objective('ENTER THE QUIET ROOM');}else{doorProgress=Math.min(1,phaseTime/.8);hinge.rotation.y=-Math.PI/2*(1-doorProgress);if(doorProgress===1){phase='locked';phaseTime=0;verity.visible=false;sound(62,.35,.18,'sawtooth');setTimeout(()=>sound(170,.08,.09,'square'),230);objective('WAIT HERE');}}}
 else if(phase==='breaking'){doorProgress=Math.min(1,phaseTime/.55);hinge.rotation.y=-Math.PI/2*doorProgress;if(doorProgress===1)phase='escaped';}
 if(phase==='escaped'&&nightStarted&&player.z>6.7){phase='night_yard';phaseTime=0;}
 if(phase==='gate_opening'){doorProgress=Math.min(1,phaseTime/1.25);yardGateHinge.rotation.y=-Math.PI/2*doorProgress;if(doorProgress>=1){gateIsOpen=true;phase='gate_open';phaseTime=0;}}
 if(phase==='gate_open'&&!prisonEntered&&player.z>37.5){phase='prison';prisonEntered=true;prisonLight.intensity=34;flashlightOn=false;say('No way out.',2);sound(38,.8,.045,'sawtooth');}
 if(phase==='prison'&&!chaseStarted&&player.z>103.5)startLabChase();
 if(phase==='chase'){const target=new THREE.Vector3(player.x,.55,player.z);verityMotion.chase(target,dt,5.1);if(distance<1.2)catchPlayer();}
 if(phase==='tube_hide'){labTubeHatch.rotation.y=-Math.PI/2*Math.max(0,1-phaseTime/.8);if(phaseTime<.85){verityMotion.idle(dt,player);}else if(!tubeSearchAt){verityMotion.move(new THREE.Vector3(0,.55,124.3),dt,4.1);if(Math.hypot(verity.position.x,verity.position.z-124.3)<.8)tubeSearchAt=phaseTime;}else if(phaseTime-tubeSearchAt<2.8){verityMotion.idle(dt,player);}else if(walkNPC(new THREE.Vector3(0,.7,106),dt,4.2)){verity.visible=false;labTubeHatch.rotation.y=-Math.PI/2;phase='tube_safe';phaseTime=0;labLight.intensity=2;labAlarm.intensity=0;say('...',1);}}
 if(!verityMotion.wasMoving)verityMotion.idle(dt,player);
 if(performance.now()>dialogUntil)$('subtitle').hidden=true;
}
function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.05);if(started&&!paused&&!mazeOpen){crouching=keys.has('KeyC')||keys.has('ControlLeft')||keys.has('ControlRight');if(phase!=='wake'&&phase!=='forced_entry'&&phase!=='tube_hide')player.y+=((crouching ? .68 : 1.65)-player.y)*(1-Math.exp(-dt*12));let f=(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0),s=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0);const len=Math.hypot(f,s);if(len&&!['wake','forced_entry','tube_hide','caught'].includes(phase)){f/=len;s/=len;const speed=crouching?1.45:keys.has('ShiftLeft')?4:2.5;const dx=(-Math.sin(yaw)*f+Math.cos(yaw)*s)*speed*dt,dz=(-Math.cos(yaw)*f-Math.sin(yaw)*s)*speed*dt;if(!blocked(player.x+dx,player.z))player.x+=dx;if(!blocked(player.x,player.z+dz))player.z+=dz;player.x=Math.max(-21.5,Math.min(21.5,player.x));player.z=Math.max(-26.1,Math.min(147,player.z));footTimer+=dt;if(footTimer>.48){footTimer=0;sound(player.z>7?75:105,.055,.018,'triangle');}}updateStory(dt);}const indoors=player.z<6.6;if(nightStarted){hemi.intensity=.035;hallLight.intensity=0;quietLight.intensity=0;sun.intensity=0;}else{hemi.intensity=indoors?1.15:2.2;hallLight.intensity=indoors?18:0;quietLight.intensity=indoors?13:0;}
camera.position.copy(player);camera.rotation.set(pitch,yaw,wakeRoll);camera.updateMatrixWorld(true);flashSpot.intensity=flashlightOn?68:0;flashModel.visible=hasFlashlight;flashlight.visible=nightStarted&&!hasFlashlight;const beamDirection=new THREE.Vector3();camera.getWorldDirection(beamDirection);flashTarget.position.copy(camera.position).addScaledVector(beamDirection,18);showInteractions();encounterMusic.update(started&&!paused&&!mazeOpen&&['greeting','follow','await_entry','departure'].includes(phase));renderer.render(scene,camera);}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();
// Batch stationary objects by material, retaining the collision boxes built above.
// This removes hundreds of draw calls from the original model preview.
function batchScenery(){scene.updateMatrixWorld(true);const groups=new Map();for(const o of [...scene.children]){if(!o.isMesh||o===marble||o===blades||!o.geometry.attributes.normal||Array.isArray(o.material))continue;const key=o.material.uuid;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(o);}for(const objects of groups.values()){if(objects.length<3)continue;const parts=objects.map(o=>{const g=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();return g.applyMatrix4(o.matrixWorld);});const geometry=new THREE.BufferGeometry();for(const name of ['position','normal','uv']){if(parts.some(g=>!g.attributes[name]))continue;const size=parts[0].attributes[name].itemSize,total=parts.reduce((n,g)=>n+g.attributes[name].array.length,0),array=new Float32Array(total);let offset=0;for(const g of parts){array.set(g.attributes[name].array,offset);offset+=g.attributes[name].array.length;}geometry.setAttribute(name,new THREE.BufferAttribute(array,size));}const merged=new THREE.Mesh(geometry,objects[0].material);merged.castShadow=true;merged.receiveShadow=true;scene.add(merged);for(const o of objects)scene.remove(o);for(const g of parts)g.dispose();}renderer.setPixelRatio(Math.min(devicePixelRatio,1.25));renderer.shadowMap.autoUpdate=false;renderer.shadowMap.needsUpdate=true;verity.traverse(o=>{if(o.isMesh)o.castShadow=false;});}
batchScenery();
buildInteractables();
// Initially face Verity across the grass.
yaw=Math.PI;frame();
window.addEventListener('error',e=>{if(!started){$('load-error').hidden=false;$('load-error').textContent='The game could not start: '+e.message;}});

